-- Generated by scripts/rebuild-pack.ts: what the migrations set up outside the public schema
-- (Supabase Storage buckets and their access rules, triggers on auth tables, realtime tables,
-- and who may receive which realtime broadcast topic).
-- Load after schema.sql and seed.sql.

insert into storage.buckets (id, name, public) values ('avatars', 'avatars', 'f') on conflict (id) do nothing;
insert into storage.buckets (id, name, public) values ('report-files', 'report-files', 'f') on conflict (id) do nothing;
insert into storage.buckets (id, name, public) values ('reports', 'reports', 'f') on conflict (id) do nothing;
insert into storage.buckets (id, name, public) values ('selfies', 'selfies', 'f') on conflict (id) do nothing;

drop policy if exists "Field members read their own topic" on realtime.messages;
create policy "Field members read their own topic" on realtime.messages as PERMISSIVE for SELECT to authenticated
  using ((realtime.topic() = field_topic(( SELECT auth.uid() AS uid))));

drop policy if exists "Followers read their own follow topic" on realtime.messages;
create policy "Followers read their own follow topic" on realtime.messages as PERMISSIVE for SELECT to authenticated
  using (can_hear_follow(realtime.topic()));

drop policy if exists avatars_insert_own on storage.objects;
create policy avatars_insert_own on storage.objects as PERMISSIVE for INSERT to public
  with check (((bucket_id = 'avatars'::text) AND ((storage.foldername(name))[1] = (auth.uid())::text)));

drop policy if exists avatars_read on storage.objects;
create policy avatars_read on storage.objects as PERMISSIVE for SELECT to public
  using (((bucket_id = 'avatars'::text) AND (((storage.foldername(name))[1] = (auth.uid())::text) OR is_admin() OR supervises_user(((storage.foldername(name))[1])::uuid))));

drop policy if exists report_files_delete_own on storage.objects;
create policy report_files_delete_own on storage.objects as PERMISSIVE for DELETE to public
  using (((bucket_id = 'report-files'::text) AND ((storage.foldername(name))[1] = (auth.uid())::text) AND (NOT report_file_attached(name))));

drop policy if exists report_files_insert_own on storage.objects;
create policy report_files_insert_own on storage.objects as PERMISSIVE for INSERT to public
  with check (((bucket_id = 'report-files'::text) AND ((storage.foldername(name))[1] = (auth.uid())::text) AND can_file_report()));

drop policy if exists report_files_read on storage.objects;
create policy report_files_read on storage.objects as PERMISSIVE for SELECT to public
  using (((bucket_id = 'report-files'::text) AND report_file_readable(name)));

drop policy if exists reports_delete_own_sameday on storage.objects;
create policy reports_delete_own_sameday on storage.objects as PERMISSIVE for DELETE to public
  using (((bucket_id = 'reports'::text) AND ((storage.foldername(name))[1] = (auth.uid())::text)));

drop policy if exists reports_insert_own on storage.objects;
create policy reports_insert_own on storage.objects as PERMISSIVE for INSERT to public
  with check (((bucket_id = 'reports'::text) AND ((storage.foldername(name))[1] = (auth.uid())::text)));

drop policy if exists reports_read on storage.objects;
create policy reports_read on storage.objects as PERMISSIVE for SELECT to public
  using (((bucket_id = 'reports'::text) AND (((storage.foldername(name))[1] = (auth.uid())::text) OR is_admin())));

drop policy if exists reports_update_own on storage.objects;
create policy reports_update_own on storage.objects as PERMISSIVE for UPDATE to public
  using (((bucket_id = 'reports'::text) AND ((storage.foldername(name))[1] = (auth.uid())::text)))
  with check (((bucket_id = 'reports'::text) AND ((storage.foldername(name))[1] = (auth.uid())::text)));

drop policy if exists selfies_insert_own on storage.objects;
create policy selfies_insert_own on storage.objects as PERMISSIVE for INSERT to public
  with check (((bucket_id = 'selfies'::text) AND ((storage.foldername(name))[1] = (auth.uid())::text)));

drop policy if exists selfies_read on storage.objects;
create policy selfies_read on storage.objects as PERMISSIVE for SELECT to public
  using (((bucket_id = 'selfies'::text) AND (((storage.foldername(name))[1] = (auth.uid())::text) OR is_admin())));



